import CategoryOutlinedIcon from '@mui/icons-material/CategoryOutlined';
import CloudUploadOutlinedIcon from '@mui/icons-material/CloudUploadOutlined';
import * as React from 'react';
import { useMemo } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  Slide,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import { TransitionProps } from '@mui/material/transitions';
import { ICategory } from '../../../core/Interface/category.interface';
import { useFormik } from 'formik';
import { useSaveCategoryMutation } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors, HEADER_GRADIENT } from '../../../theme/appColors';
import { useTranslation } from 'react-i18next';
import { uploadImage } from '../../../core/utils';

interface INewCategory {
  openModel?: boolean;
  title: string;
  handleCloseDialog: () => void;
  data?: ICategory;
  isImageEnabled: boolean;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': {
      borderColor: alpha(appColors.blueGreyishLight[80], 0.16),
    },
    '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
    '&.Mui-focused': {
      boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}`,
    },
    '&.Mui-focused fieldset': { borderColor: '#2563EB' },
  },
};

const labelSx = {
  color: '#142352',
  fontSize: '0.86rem',
  fontWeight: 700,
  mb: 0.8,
};

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & {
    children: React.ReactElement<string, string>;
  },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

// eslint-disable-next-line react/no-multi-comp
const NewCategory = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
  isImageEnabled,
}: INewCategory) => {
  const [open] = React.useState(openModel);
  const [saveCategory, { isLoading }] = useSaveCategoryMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common']);

  const [selectedImage, setSelectedImage] = React.useState<
    File | undefined
  >(undefined);
  const [isImageUploading, setIsImageUploading] = React.useState(false);

  const formik = useFormik({
    initialValues: {
      name: data?.name ?? '',
      code: data?.code ?? '',
      imageUrl: data?.imageUrl ?? '',
    },
    onSubmit: async (values) => {
      try {
        let imageUrl: string | undefined = data?.imageUrl;

        if (selectedImage) {
          setIsImageUploading(true);
          imageUrl = (await uploadImage(selectedImage)) || '';
          setIsImageUploading(false);
        }

        const temData: Partial<ICategory> = {
          code: values.code,
          name: values.name,
          imageUrl,
        };

        if (data?.id) temData.id = data.id;

        const res = await saveCategory(temData).unwrap();
        if (!res.status) {
          showErrorMessage(res.message);
        } else {
          showMessage(res.message);
          handleCloseDialog();
        }
      } catch (error) {
        setIsImageUploading(false);
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(
    () =>
      !!formik.values.name?.trim() && !!formik.values.code?.trim(),
    [formik.values.name, formik.values.code]
  );

  const handleImageChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = event.target.files;
    setSelectedImage(files && files.length > 0 ? files[0] : undefined);
  };

  const buttonText = data ? t('common:update') : t('common:create');
  const isBusy = isLoading || isImageUploading;

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        onSubmit: formik.handleSubmit,
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth="sm"
      onClose={handleCloseDialog}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
              <CategoryOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Create or edit category</Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      {/* Body */}
      <DialogContent sx={{ px: 3, pt: 3, pb: 1 }}>
        <Box>
          <Box sx={{ mb: 2.5 }}>
            <Typography sx={labelSx}>Category Code</Typography>
            <TextField
              autoComplete="off"
              fullWidth
              placeholder="e.g. ELEC"
              size="small"
              sx={inputFieldSx}
              {...formik.getFieldProps('code')}
            />
          </Box>

          <Box sx={{ mb: isImageEnabled ? 2.5 : 0 }}>
            <Typography sx={labelSx}>Category Name</Typography>
            <TextField
              autoComplete="off"
              fullWidth
              placeholder="e.g. Electronics"
              size="small"
              sx={inputFieldSx}
              {...formik.getFieldProps('name')}
            />
          </Box>

          {isImageEnabled && (
            <Box>
              <Typography sx={labelSx}>Category Image</Typography>
              <Box
                sx={{
                  background: alpha(appColors.blueGreyishLight[80], 0.04),
                  border: `1px dashed ${alpha(
                    appColors.blueGreyishLight[80],
                    0.25
                  )}`,
                  borderRadius: '6px',
                  p: 2.5,
                  textAlign: 'center',
                }}
              >
                {(selectedImage || data?.imageUrl) && (
                  <Box
                    sx={{ mb: 2, textAlign: 'center' }}
                  >
                    <Box
                      alt="Preview"
                      component="img"
                      src={
                        selectedImage
                          ? URL.createObjectURL(selectedImage)
                          : data?.imageUrl
                      }
                      sx={{
                        borderRadius: '6px',
                        height: 130,
                        objectFit: 'cover',
                        width: '100%',
                      }}
                    />
                  </Box>
                )}

                <Button
                  component="label"
                  startIcon={<CloudUploadOutlinedIcon />}
                  sx={{
                    borderColor: alpha('#2563EB', 0.3),
                    borderRadius: '6px',
                    color: '#2563EB',
                    fontWeight: 600,
                    textTransform: 'none',
                    '&:hover': {
                      background: alpha('#2563EB', 0.05),
                      borderColor: alpha('#2563EB', 0.5),
                    },
                  }}
                  variant="outlined"
                >
                  {selectedImage || data?.imageUrl
                    ? 'Change Image'
                    : 'Choose Image'}
                  <input
                    hidden
                    onChange={handleImageChange}
                    type="file"
                  />
                </Button>

                {isImageUploading && (
                  <Box sx={{ mt: 1.5 }}>
                    <CircularProgress
                      size={18}
                      sx={{ color: '#2563EB' }}
                    />
                  </Box>
                )}

                {selectedImage && (
                  <Typography
                    sx={{
                      color: alpha('#142352', 0.5),
                      fontSize: '0.75rem',
                      mt: 1,
                    }}
                  >
                    {selectedImage.name}
                  </Typography>
                )}
              </Box>
            </Box>
          )}
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
          <Button
            onClick={handleCloseDialog}
            sx={{
              borderColor: '#CBD5E1',
              borderRadius: '8px',
              color: '#475569',
              fontWeight: 600,
              height: 40,
              minWidth: 110,
              px: 3,
              textTransform: 'none',
              '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
            }}
            variant="outlined"
          >
            {t('common:cancel')}
          </Button>

          <Button
            disabled={!formValid || isBusy}
            sx={{
              background: HEADER_GRADIENT,
              borderRadius: '8px',
              boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
              color: '#fff',
              fontWeight: 700,
              height: 40,
              minWidth: 110,
              px: 3,
              textTransform: 'none',
              '&:hover': { opacity: 0.9 },
              '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' },
            }}
            type="submit"
            variant="contained"
          >
            {isBusy && (
              <CircularProgress
                size={14}
                sx={{ color: '#fff', mr: 1 }}
              />
            )}
            {buttonText}
          </Button>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(NewCategory);
