import AddIcon from '@mui/icons-material/Add';
import CategoryOutlinedIcon from '@mui/icons-material/CategoryOutlined';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import Inventory2OutlinedIcon from '@mui/icons-material/Inventory2Outlined';
import {
  Box,
  Button,
  Card,
  CardActions,
  CardContent,
  Grid,
  IconButton,
  Skeleton,
  TextField,
  Tooltip,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { ICategory } from '../../core/Interface/category.interface';
import { useNotifier } from '../../core/Notifier';
import useUser from '../../core/hooks/useUser';
import { Privileges } from '../../core/types/commonType';
import { appColors, HEADER_GRADIENT } from '../../theme/appColors';
import {
  useDeleteCategoryMutation,
  useGetCategoryQuery,
  useGetUserQuery,
} from '../posApi';
import NewCategory from './components/NewCategory';
import AnimatedPage from '../../layouts/AnimatedPage';

const accentColors = [
  '#F97316',
  '#06B6D4',
  '#8B5CF6',
  '#22C55E',
  '#0EA5E9',
  '#EC4899',
  '#F59E0B',
  '#14B8A6',
];

const Category = () => {
  const { data, isLoading } = useGetCategoryQuery({
    pageIndex: 0,
    pageSize: 20,
    searchText: '',
  });
  const { t } = useTranslation(['common', 'category']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();

  const [categoryData, setCategoryData] = useState<ICategory>();
  const [openAddCategory, setOpenAddCategory] = useState(false);
  const [openDeleteCategory, setOpenDeleteCategory] = useState(false);
  const [categoryNameToDelete, setCategoryNameToDelete] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const [deleteCategory] = useDeleteCategoryMutation();

  const categoryList = useMemo(
    () => (data?.data as ICategory[]) || [],
    [data?.data]
  );

  const filteredCategoryList = useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    return categoryList.filter(
      (value) =>
        value.name.toLowerCase().includes(query) ||
        value.code.toLowerCase().includes(query)
    );
  }, [categoryList, searchQuery]);

  const { data: companyData } = useGetUserQuery();

  const isImageEnabled = useMemo(() => {
    if (
      companyData?.data &&
      typeof companyData.data === 'object' &&
      'company' in companyData.data
    ) {
      return (
        (companyData.data as { company: { isImageEnabled: boolean } }).company
          .isImageEnabled ?? false
      );
    }
    return false;
  }, [companyData]);

  const handleDelete = async (id: string) => {
    try {
      const response = await deleteCategory(id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteCategory(false);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  return (
    <AnimatedPage>
      {/* Hero banner */}
      <Box
        sx={{
          mb: 3,
          px: { xs: 2, md: 3 },
          py: { xs: 1.5, md: 2 },
          borderRadius: 2,
          color: '#fff',
          background: HEADER_GRADIENT,
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        {/* Decorative circles */}
        <Box
          sx={{
            pointerEvents: 'none',
            position: 'absolute',
            inset: 'auto -60px -100px auto',
            width: 220,
            height: 220,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.07)',
          }}
        />
        <Box
          sx={{
            pointerEvents: 'none',
            position: 'absolute',
            inset: '-100px auto auto 55%',
            width: 260,
            height: 260,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.05)',
          }}
        />

        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: '20px',
            justifyContent: 'space-between',
            position: 'relative',
          }}
        >
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.14)',
                backdropFilter: 'blur(8px)',
                border: '1px solid rgba(255,255,255,0.18)',
                borderRadius: '10px',
                display: 'flex',
                height: 44,
                justifyContent: 'center',
                width: 44,
              }}
            >
              <CategoryOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography
                sx={{
                  color: '#fff',
                  fontSize: { xs: '1rem', md: '1.2rem' },
                  fontWeight: 800,
                  letterSpacing: '-0.02em',
                  lineHeight: 1.2,
                }}
              >
                {t('category:category')}
              </Typography>
              <Typography
                sx={{
                  color: 'rgba(255,255,255,0.72)',
                  fontSize: '0.78rem',
                }}
              >
                {isLoading
                  ? '—'
                  : `${categoryList.length} ${t('category:category').toLowerCase()}${
                      categoryList.length !== 1 ? 's' : ''
                    } total`}
              </Typography>
            </Box>
          </Box>

          <Box sx={{ alignItems: 'center', display: 'flex', gap: '20px' }}>
            <TextField
              autoComplete="off"
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by name or code…"
              size="small"
              sx={{
                width: 240,
                '& .MuiOutlinedInput-input': { color: '#fff', fontSize: 13, '&::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 } },
                '& .MuiOutlinedInput-root': {
                  backdropFilter: 'blur(8px)',
                  backgroundColor: 'rgba(255,255,255,0.12)',
                  borderRadius: '8px',
                  height: 40,
                  '& fieldset': { borderColor: 'rgba(255,255,255,0.22)' },
                  '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.45)' },
                  '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.7)' },
                },
              }}
              value={searchQuery}
            />

            {userHasRight(Privileges.CategoryAdd) && (
              <Button
                onClick={() => {
                  setCategoryData(undefined);
                  setOpenAddCategory(true);
                }}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                {t('category:addCategory')}
              </Button>
            )}
          </Box>
        </Box>
      </Box>

      {/* Cards grid */}
      <Grid
        container
        spacing={2}
      >
        {isLoading &&
          [1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
            <Grid
              item
              key={i}
              xl={2}
              lg={3}
              md={4}
              sm={6}
              xs={12}
            >
              <Skeleton
                height={140}
                sx={{ borderRadius: '8px' }}
                variant="rectangular"
              />
            </Grid>
          ))}

        {!isLoading &&
          filteredCategoryList.map((value, index) => {
            const accent = accentColors[index % accentColors.length];
            return (
              <Grid
                item
                key={value.id ?? index}
                xl={2}
                lg={3}
                md={4}
                sm={6}
                xs={12}
              >
                <Card
                  sx={{
                    background: `linear-gradient(145deg, rgba(255,255,255,0.98) 0%, ${alpha(accent, 0.07)} 100%)`,
                    border: `1px solid ${alpha(accent, 0.22)}`,
                    borderRadius: '8px',
                    overflow: 'hidden',
                    position: 'relative',
                  }}
                  variant="outlined"
                >
                  {/* Accent top bar */}
                  <Box
                    sx={{
                      background: `linear-gradient(90deg, ${accent} 0%, ${alpha(accent, 0.55)} 100%)`,
                      height: 3,
                      width: '100%',
                    }}
                  />

                  {value.imageUrl && (
                    <Box
                      component="img"
                      src={value.imageUrl}
                      sx={{
                        height: 120,
                        objectFit: 'cover',
                        width: '100%',
                      }}
                    />
                  )}

                  <CardContent sx={{ pb: '8px !important', pt: 1.5 }}>
                    <Box
                      sx={{
                        alignItems: 'flex-start',
                        display: 'flex',
                        gap: 1.5,
                      }}
                    >
                      {/* Icon */}
                      <Box
                        sx={{
                          alignItems: 'center',
                          background: alpha(accent, 0.12),
                          borderRadius: '8px',
                          color: accent,
                          display: 'flex',
                          flexShrink: 0,
                          height: 36,
                          justifyContent: 'center',
                          width: 36,
                        }}
                      >
                        <CategoryOutlinedIcon sx={{ fontSize: 18 }} />
                      </Box>

                      {/* Name & code */}
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        {value.name.length > 18 ? (
                          <Tooltip
                            arrow
                            title={value.name}
                          >
                            <Typography
                              sx={{
                                color: '#142352',
                                cursor: 'pointer',
                                fontSize: 14,
                                fontWeight: 700,
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap',
                              }}
                            >
                              {value.name.slice(0, 18)}…
                            </Typography>
                          </Tooltip>
                        ) : (
                          <Typography
                            sx={{
                              color: '#142352',
                              fontSize: 14,
                              fontWeight: 700,
                            }}
                          >
                            {value.name}
                          </Typography>
                        )}

                        {value.code.length > 14 ? (
                          <Tooltip
                            arrow
                            title={value.code}
                          >
                            <Typography
                              sx={{
                                color: alpha('#142352', 0.5),
                                cursor: 'pointer',
                                fontSize: 11,
                                fontWeight: 500,
                              }}
                            >
                              {value.code.slice(0, 14)}…
                            </Typography>
                          </Tooltip>
                        ) : (
                          <Typography
                            sx={{
                              color: alpha('#142352', 0.5),
                              fontSize: 11,
                              fontWeight: 500,
                            }}
                          >
                            {value.code}
                          </Typography>
                        )}
                      </Box>

                      {/* Product count badge */}
                      <Box
                        sx={{
                          alignItems: 'center',
                          background: alpha(accent, 0.1),
                          border: `1px solid ${alpha(accent, 0.25)}`,
                          borderRadius: '8px',
                          display: 'flex',
                          flexDirection: 'column',
                          flexShrink: 0,
                          justifyContent: 'center',
                          minWidth: 40,
                          px: 1,
                          py: 0.5,
                        }}
                      >
                        <Typography
                          sx={{
                            color: accent,
                            fontSize: 14,
                            fontWeight: 800,
                            lineHeight: 1,
                          }}
                        >
                          {value.productCount}
                        </Typography>
                        <Box
                          sx={{
                            alignItems: 'center',
                            display: 'flex',
                            gap: 0.25,
                            mt: 0.3,
                          }}
                        >
                          <Inventory2OutlinedIcon
                            sx={{ color: accent, fontSize: 9 }}
                          />
                          <Typography
                            sx={{
                              color: accent,
                              fontSize: 9,
                              fontWeight: 600,
                              letterSpacing: '0.3px',
                            }}
                          >
                            items
                          </Typography>
                        </Box>
                      </Box>
                    </Box>
                  </CardContent>

                  {(userHasRight(Privileges.CategoryEdit) ||
                    userHasRight(Privileges.CategoryDelete)) && (
                    <CardActions
                      sx={{
                        borderTop: `1px solid ${alpha(accent, 0.12)}`,
                        justifyContent: 'flex-end',
                        pb: 1,
                        pt: 0.75,
                        px: 1.5,
                      }}
                    >
                      {userHasRight(Privileges.CategoryEdit) && (
                        <IconButton
                          onClick={() => {
                            setCategoryData(value);
                            setOpenAddCategory(true);
                          }}
                          size="small"
                          sx={{
                            background: alpha('#F97316', 0.1),
                            borderRadius: '6px',
                            height: 30,
                            width: 30,
                            '&:hover': {
                              background: alpha('#F97316', 0.18),
                            },
                          }}
                        >
                          <EditIcon
                            sx={{ color: '#F97316', fontSize: 15 }}
                          />
                        </IconButton>
                      )}

                      {userHasRight(Privileges.CategoryDelete) && (
                        <IconButton
                          onClick={() => {
                            setCategoryData(value);
                            setCategoryNameToDelete(value.name);
                            setOpenDeleteCategory(true);
                          }}
                          size="small"
                          sx={{
                            background: alpha(
                              appColors.carmineRed[30],
                              0.1
                            ),
                            borderRadius: '6px',
                            height: 30,
                            width: 30,
                            '&:hover': {
                              background: alpha(
                                appColors.carmineRed[30],
                                0.18
                              ),
                            },
                          }}
                        >
                          <DeleteIcon
                            sx={{
                              color: appColors.carmineRed[30],
                              fontSize: 15,
                            }}
                          />
                        </IconButton>
                      )}
                    </CardActions>
                  )}
                </Card>
              </Grid>
            );
          })}

        {!isLoading && filteredCategoryList.length === 0 && (
          <Grid
            item
            xs={12}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: alpha(appColors.blueGreyishLight[80], 0.04),
                border: `1px dashed ${alpha(appColors.blueGreyishLight[80], 0.25)}`,
                borderRadius: '8px',
                display: 'flex',
                flexDirection: 'column',
                gap: 1,
                py: 6,
              }}
            >
              <CategoryOutlinedIcon
                sx={{ color: alpha('#142352', 0.2), fontSize: 40 }}
              />
              <Typography
                sx={{ color: alpha('#142352', 0.4), fontWeight: 600 }}
              >
                {t('common:noData')}
              </Typography>
            </Box>
          </Grid>
        )}
      </Grid>

      {openAddCategory && (
        <NewCategory
          data={categoryData}
          handleCloseDialog={() => setOpenAddCategory(false)}
          isImageEnabled={isImageEnabled}
          openModel={openAddCategory}
          title={`${
            categoryData ? t('category:edit') : t('category:createNew')
          } ${t('category:category')}`}
        />
      )}

      {openDeleteCategory && (
        <DeletePopup
          content={`${t('category:confirmMessage')} "${categoryNameToDelete}"?`}
          handleCloseDelete={() => setOpenDeleteCategory(false)}
          onConfirm={async () => {
            await handleDelete(categoryData?.id || '');
          }}
          open={openDeleteCategory}
          title={t('category:deleteCategory')}
        />
      )}
    </AnimatedPage>
  );
};

export default Category;
